// Flat lookup map with canonical category priority
const SPECS = {};
const CATEGORY_PRIORITY = [
  'banners', 'flags', 'table-covers', 'signs-decals', 'marketing-materials',
  'stands-displays', 'trade-show', 'compliance-signs', 'led-signs', 'boxes-packaging', 'apparel'
];

CATEGORY_PRIORITY.forEach(catKey => {
  const cat = CATEGORIES[catKey];
  if (!cat) return;
  Object.entries(cat.products).forEach(([slug, pr]) => {
    if (!SPECS[slug]) {
      pr.slug = slug;
      pr._catKey = catKey;
      SPECS[slug] = pr;
    }
  });
});

// Production Aliases and Fallbacks
const PRODUCTION_SPEC_ALIASES = {
  'custom-table-covers': 'fitted-table-covers',
  'table-covers': 'fitted-table-covers',
  'table-cover': 'fitted-table-covers',
  'die-cut-yard-signs': 'die-cut-yard-signs',
  'vinyl-banners': 'custom-vinyl-banners',
  'truck-magnetic-signs': 'vehicle-magnetic-signs',
  'magnetic-signs': 'vehicle-magnetic-signs',
  'poster-paper': 'vinyl-posters',
  'desk-flags': 'desk-flags-blade',
  'desk-flags-blade': 'desk-flags-blade',
  'desk-flags-teardrop': 'desk-flags-teardrop'
};
Object.entries(PRODUCTION_SPEC_ALIASES).forEach(([alias, target]) => {
  if (SPECS[target] && !SPECS[alias]) {
    SPECS[alias] = Object.assign({}, SPECS[target], { slug: alias, originalSlug: target });
  }
});

